import sys
from math import isqrt

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    M = int(input_data[1])
    P = [int(x) for x in input_data[2:2+N]]

    # Sorting allows us to break out of our evaluation loops early 
    P.sort()
    max_P = P[-1]

    # T_high is safely bound by the maximum possible marginal cost
    T_high = 2 * isqrt(M * max_P) + 2 * max_P + 10

    lo = 0
    hi = T_high

    while lo < hi:
        mid = (lo + hi + 1) // 2
        cost = 0
        for p in P:
            # If the base price exceeds the threshold, marginal cost evaluates to 0 units
            if p > mid:
                break
            k = (mid + p) // (2 * p)
            cost += k * k * p

            # If total cost exceeds M, we already know this 'mid' is invalid; break early
            if cost > M:
                break

        if cost <= M:
            lo = mid
        else:
            hi = mid - 1

    T = lo
    cost = 0
    units = 0

    # Re-evaluate properties using our discovered maximum T
    for p in P:
        if p > T:
            break
        k = (T + p) // (2 * p)
        units += k
        cost += k * k * p

    # Any remaining budget can exactly afford marginal units priced at T + 1
    extra = (M - cost) // (T + 1)
    print(units + extra)

